    48→export function TraktProvider({ children }: { children: ReactNode }) {
    49→  const traktIntegration = useTraktIntegration();
    50→
    51→  // Add maintenance mode values to the context
    52→  const contextValue: TraktContextProps = {
    53→    ...traktIntegration,
    54→    isMaintenanceMode: traktService.isMaintenanceMode(),
    55→    maintenanceMessage: traktService.getMaintenanceMessage(),
    56→  };
    57→
    58→  return (
    59→    <TraktContext.Provider value={contextValue}>
    60→      {children}
    61→    </TraktContext.Provider>
    62→  );
    63→}
    64→
    65→export function useTraktContext() {
    66→  const context = useContext(TraktContext);
    67→  if (context === undefined) {
    68→    throw new Error('useTraktContext must be used within a TraktProvider');
    69→  }
    70→  return context;
    71→} 

